/** S500L020CONTRATO_C: una función por consulta, cada una con su propio tipo de respuesta. */
public sealed interface ConsultaContrato permits DatosGenerales, SaldoCompleto, SaldoParcial,
        SaldosSbc, SaldoPromedio, ExencionUma { }

public record Resultado<T extends ConsultaContrato>(int codigo, Optional<T> datos) {
    // 0 éxito · 2 función inválida · 3 no existe · 4 error DMSII · 5 reintente · 6 no pertenece al CSI ...
}

@Service
@RequiredArgsConstructor
@Transactional(readOnly = true)                 // OPEN INQUIRY: sin escrituras DMSII
public class SaldosCaptacionService {

    public Resultado<? extends ConsultaContrato> contrato(SolicitudContrato s) {
        // El estado ya no es global: cada llamada trabaja con objetos locales y no necesita
        // el evento E_ACCESO_DB que serializaba a un consumidor por vez.
        return switch (s.funcion()) {
            case 1 -> datosGenerales(s);
            case 2 -> saldo(s);
            case 3 -> saldoParcial(s);
            case 4 -> saldosSbc(s);
            case 5 -> saldoPromedio(s);
            case 6 -> exencionUma(s);
            default -> new Resultado<>(2, Optional.empty());   // FUNCION INVALIDA
        };
    }
}

import io.vavr.control.Either;   // izquierda = código de resultado; derecha = dato

public enum BaseCaptacion { CAPTACION, AUXILIAR }

/** SELECCIONA_BASE: durante el batch la verdad vive en la auxiliar; si el contrato no está, se cae a captación. */
@Component
@RequiredArgsConstructor
public class BaseCaptacionRouter {

    private final ContratoRepository captacion;     // S500B03CONTRATOS  (S500BD01CAPTACION)
    private final ContratoAuxRepository auxiliar;   // S500B03AUXCTOS    (S500BD02AUXILIAR)
    private final EstadoBases estado;               // B_BDCAPTACION_OPEN / B_BDAUXILIAR_OPEN

    public record Seleccion(BaseCaptacion base, Contrato contrato) {}

    public Either<Integer, Seleccion> selecciona(String numContrato) {
        if (!estado.captacionAbierta() && !estado.auxiliarAbierta()) return Either.left(5);
        if (estado.auxiliarAbierta()) {
            var aux = auxiliar.findById(numContrato);
            if (aux.isPresent()) return Either.right(new Seleccion(BaseCaptacion.AUXILIAR, aux.get()));
            if (!estado.captacionAbierta()) return Either.left(5);          // REINTENTE MAS TARDE
        }
        return captacion.findById(numContrato)
                .<Either<Integer, Seleccion>>map(c -> Either.right(new Seleccion(BaseCaptacion.CAPTACION, c)))
                .orElse(Either.left(3));                                    // NO EXISTE REGISTRO
    }
}

@Component
@RequiredArgsConstructor
public class MedioAccesoResolver {

    private final MedioAccesoS016Client l458;     // S016_L458_BUSCA_MDA
    private final SaldosProperties props;         // csi del sistema, antes en variable global
    private final MeterRegistry metricas;         // reemplaza S500L030 (instrumentación de tiempos)

    public record Contrato(String numero, int statusMda) {}

    public Either<Integer, Contrato> resuelve(int tipoMda, String mda16) {
        if (tipoMda == 0) return Either.right(new Contrato(mda16, 0));     // el MDA ya es el contrato
        var r = metricas.timer("s016.busca_mda").record(() -> l458.buscaMda(mda16));
        if (r.errorDms() > 0)            return Either.left(9);            // MEDIO DE ACCESO INEXISTENTE
        if (r.csi() != props.csi())      return Either.left(6);            // NO PERTENECE AL CSI
        return Either.right(new Contrato(r.cuentaSalida(), r.status()));
    }
}

@Component
public class SaldoDisponibleCalculator {

    public record Saldos(BigDecimal actual, BigDecimal disponible, BigDecimal pendiente) {}

    /** SALDO_DISP. Importes en pesos con escala 2; el fuente los lleva en centavos enteros. */
    public Saldos calcula(SaldoContrato b03, BaseCaptacion base, TipoProceso proceso, LocalDate fechaLinea) {
        BigDecimal actual = b03.saldoActual(), pendiente = b03.saldoPendiente(), protegido = b03.saldoProtegido();

        // (a) corte no aplicado en batch sobre captación
        if (base == BaseCaptacion.CAPTACION && proceso == TipoProceso.BATCH
                && !fechaLinea.equals(b03.fechaSaldoPendiente())) {
            actual = actual.add(pendiente);
            pendiente = b03.saldoSbc().add(b03.sbcUnDia());
            protegido = BigDecimal.ZERO;
        }
        // (b) y (c)
        BigDecimal disponible = actual;
        actual = actual.add(pendiente);
        if (b03.indicadorSaldoPendiente() == 1) {
            disponible = disponible.add(pendiente.subtract(protegido));
            pendiente = protegido;
        }
        // (d) el pago por cobrar caduca en línea fuera de la ventana ciega
        BigDecimal pagoPorCobrar = (proceso == TipoProceso.LINEA
                && !fechaLinea.equals(b03.fechaVentanaCiega())) ? BigDecimal.ZERO : b03.pagoPorCobrar();
        // (e) cinco retenciones y piso en cero
        disponible = disponible
                .subtract(b03.saldoTesDisponible())
                .subtract(b03.cargoPendienteSabado())
                .subtract(b03.autorizacionesPendientes())
                .subtract(b03.saldoBloqueadoGce())
                .subtract(pagoPorCobrar)
                .max(BigDecimal.ZERO);
        return new Saldos(actual, disponible, pendiente);
    }
}

