@Component
@RequiredArgsConstructor
public class ConversionDolares {

    private final SaldosProperties props;

    /**
     * SALDO_ACT_CTAMAE_DLS_MN y SALDO_ACT_CTAPER_DLS_MN. Los tipos de cambio llegan como
     * BigDecimal con su escala real, así que no hace falta el factor 10000 del fuente.
     */
    public Optional<BigDecimal> enPesos(ProductoKey p, BigDecimal saldoDolares, TiposCambio tc) {
        return props.dolares().stream()
                .filter(d -> d.coincide(p))
                .findFirst()
                .map(d -> saldoDolares.multiply(tc.de(d.tipoCambio()))
                                      .setScale(2, RoundingMode.DOWN));   // DIV entera del fuente: trunca
    }
}

/** VALIDA_FECHAS_B52: acumulados de S500B52CTRLDEPRET vigentes a la fecha de línea. */
public record AcumuladosDepRet(BigDecimal depDia, BigDecimal depMes, BigDecimal retDia,
                               BigDecimal retMes, BigDecimal saldoConsolidadoDep) {

    static final AcumuladosDepRet CERO = new AcumuladosDepRet(
            BigDecimal.ZERO, BigDecimal.ZERO, BigDecimal.ZERO, BigDecimal.ZERO, BigDecimal.ZERO);

    public AcumuladosDepRet vigentesA(LocalDate fechaAcumulado, LocalDate fechaLinea) {
        if (!YearMonth.from(fechaAcumulado).equals(YearMonth.from(fechaLinea))) {
            return CERO;                                               // cambió el mes: todo caduca
        }
        if (fechaAcumulado.getDayOfMonth() != fechaLinea.getDayOfMonth()) {
            return new AcumuladosDepRet(BigDecimal.ZERO, depMes, BigDecimal.ZERO, retMes, BigDecimal.ZERO);
        }
        return this;                                                   // mismo día: se conservan
    }
}

/** SALDO (función 2): cada paso corta la cadena si devuelve un código distinto de 0. */
private Resultado<SaldoCompleto> saldo(SolicitudContrato s) {
    return mda.resuelve(s.tipoMda(), s.mda())
        .flatMap(c -> router.selecciona(c.numero()))
        .flatMap(clonacion::valida)                                  // OBTIENE_B03_MARCLON + CHECA_CLON (20)
        .map(sel -> {
            var b03 = saldosB03.de(sel);                             // OBTIENE_B03_SDO
            var sd  = disponible.calcula(b03, sel.base(), proceso.actual(), control.fechaLinea());
            BigDecimal actual = (b03.importeSolicitudBloqueo().signum() > 0)
                    ? sd.actual().add(b03.saldoProtegidoBloqueado())  // bloqueo judicial parcial
                    : sd.actual();
            return SaldoCompleto.builder()
                    .producto(catalogo.nombre(b03.producto()))       // NOMB_PROD
                    .actual(actual).disponible(sd.disponible()).pendiente(sd.pendiente())
                    .enPesos(dolares.enPesos(b03.productoKey(), actual, control.tiposCambio()))
                    .lineaCredito(s408.saldo(b03))                    // SALDO_LINCRED
                    .comisionesPendientes(comisiones.de(b03))         // COMI_PEND
                    .ultimosMovimientos(l011.ultimos(b03, 4))          // MOVS_AD vía S151 L011 CONS_4ULT
                    .acumulados(acumulados.de(b03, control.fechaLinea()))
                    .build();
        })
        .fold(codigo -> new Resultado<>(codigo, Optional.empty()),
              ok -> new Resultado<>(0, Optional.of(ok)));
}
